def close(x, ref, rtol: float = 1e-9, atol: float = 1e-11) -> bool:
    a = np.asarray(x, dtype=float)
    r = np.asarray(ref, dtype=float)
    if a.shape != r.shape:
        print('shape', a.shape, r.shape)
        return False
    for u, v in zip(a.flat, r.flat):
        if abs(u - v) > atol + rtol * abs(v):
            print(u, v)
            return False
    return True

def check(c: bool, msg: str):
    if not c:
        print('TEST FAILED:', msg)

